(()=>{
'use strict';
const Q=new URLSearchParams(location.search);if(String(Q.get('mode')||'').toLowerCase()!=='regiondefiner')return;
const NEW_FLOW=String(Q.get('regionFlow')||'').toLowerCase()==='new',MAX_HEIGHT=Math.max(1,Math.trunc(Number(Q.get('maxHeight'))||100)),LPT=10,started=Date.now(),clamp=(v,a,b)=>Math.min(b,Math.max(a,v));
function boot(){const base=window.ShaelvienPrototype,stage=document.getElementById('stage'),world=document.getElementById('world'),loading=document.getElementById('loading');if(!base||!stage||!world){if(Date.now()-started<5000)setTimeout(boot,40);return}if(stage.dataset.markerRegionV4==='true')return;
stage.dataset.markerRegionV4='true';stage.dataset.regionVolumeV4='true';stage.dataset.regionEntry='marker';stage.classList.add('region-volume-v4');stage.classList.remove('region-tier-previewing','region-selection-only');
for(const node of stage.querySelectorAll('.region-tier-preview,.region-tier-preview-panel,.tier-preview,.tier-preview-panel,[data-region-tier-preview],.marker-panel'))node.remove();
if(loading)loading.hidden=true;try{base.showAllParallax?.()}catch{}
const source='shaelvien-regiondefiner',post=m=>{try{parent.postMessage({source,...m},location.origin)}catch{}},original={transform:world.style.transform||'',origin:world.style.transformOrigin||'',mask:world.style.maskImage||'',webkitMask:world.style.webkitMaskImage||'',clip:world.style.clipPath||''};
const cases={xy:['LASSO','RECT','ELLIPSE','CROP VIEW'],z:['DEPTH RANGE','ALL DEPTH'],saved:['NAME','SAVE REGION'],existing:['REGION']};
const s={phase:NEW_FLOW?'xy':'existing',caseIndex:0,cols:30,rows:30,xy:[],z:[],cells:[],boundary:[],minTier:0,maxTier:Math.floor((MAX_HEIGHT-1)/LPT),minLayer:0,maxLayer:MAX_HEIGHT-1,drawing:false,pid:null,regionId:String(Q.get('regionId')||''),name:'',pending:false,zoom:original.transform};
const style=document.createElement('style');style.id='marker-region-v4-style';style.textContent=`.region-volume-v4 .region-tier-preview,.region-volume-v4 .region-tier-preview-panel,.region-volume-v4 .tier-preview,.region-volume-v4 .tier-preview-panel,.region-volume-v4 [data-region-tier-preview],.region-volume-v4 .region-definition-grid,.region-volume-v4 .region-selection-tools-panel{display:none!important}.region-volume-v4 #world{display:block!important;visibility:visible!important;opacity:1!important}.marker-overlay{position:absolute;inset:0;z-index:2140;width:100%;height:100%;touch-action:none}.marker-overlay .trace{fill:rgba(73,211,255,.10);stroke:#ffd96a;stroke-width:5;stroke-linejoin:round;stroke-linecap:round;vector-effect:non-scaling-stroke}.marker-overlay .fillcell{fill:rgba(73,211,255,.24);stroke:rgba(255,255,255,.18);stroke-width:1}.marker-overlay .zband{fill:rgba(255,217,106,.2);stroke:#ffd96a;stroke-width:3}`;document.head.appendChild(style);
const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('marker-overlay');svg.setAttribute('viewBox','0 0 1000 1000');svg.setAttribute('preserveAspectRatio','none');stage.appendChild(svg);
const pnt=e=>{const r=stage.getBoundingClientRect();return{x:clamp((e.clientX-r.left)/Math.max(1,r.width),0,1),y:clamp((e.clientY-r.top)/Math.max(1,r.height),0,1)}},dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),bnds=p=>p.length?{minX:Math.min(...p.map(x=>x.x)),minY:Math.min(...p.map(x=>x.y)),maxX:Math.max(...p.map(x=>x.x)),maxY:Math.max(...p.map(x=>x.y))}:null;
function inside(x,y,p){let v=false;for(let i=0,j=p.length-1;i<p.length;j=i++){const a=p[i],b=p[j];if(((a.y>y)!==(b.y>y))&&(x<(b.x-a.x)*(y-a.y)/((b.y-a.y)||1e-9)+a.x))v=!v}return v}
function cells(){const o=[];for(let r=0;r<s.rows;r++)for(let c=0;c<s.cols;c++)if(inside((c+.5)/s.cols,(r+.5)/s.rows,s.xy))o.push(r*s.cols+c);return o}
function boundary(){const set=new Set();for(let i=1;i<s.xy.length;i++){const a=s.xy[i-1],b=s.xy[i],n=Math.max(2,Math.ceil(dist(a,b)*128));for(let k=0;k<=n;k++){const t=k/n,x=a.x+(b.x-a.x)*t,y=a.y+(b.y-a.y)*t;set.add(clamp(Math.floor(y*64),0,63)*64+clamp(Math.floor(x*64),0,63))}}return[...set].sort((a,b)=>a-b)}
function allZ(){s.minLayer=0;s.maxLayer=MAX_HEIGHT-1;s.minTier=0;s.maxTier=Math.floor((MAX_HEIGHT-1)/LPT)}function deriveZ(){const b=bnds(s.z);if(!b)return;s.minLayer=clamp(Math.floor((1-b.maxY)*MAX_HEIGHT),0,MAX_HEIGHT-1);s.maxLayer=clamp(Math.ceil((1-b.minY)*MAX_HEIGHT)-1,s.minLayer,MAX_HEIGHT-1);s.minTier=Math.floor(s.minLayer/LPT);s.maxTier=Math.floor(s.maxLayer/LPT)}
const poly=(p,c='trace')=>p.length?`<polyline class="${c}" points="${p.map(q=>`${(q.x*1000).toFixed(1)},${(q.y*1000).toFixed(1)}`).join(' ')}"/>`:'';
function activeCases(){const key=s.phase.startsWith('xy')?'xy':s.phase.startsWith('z')?'z':s.phase==='saved'?'saved':'existing';return cases[key]||['REGION']}
function activeCase(){const list=activeCases();s.caseIndex=clamp(s.caseIndex,0,list.length-1);return list[s.caseIndex]}
function labels(){const c=activeCase();if(s.phase==='xy')return{left:c,right:'DRAW BOUNDARY'};if(s.phase==='xy-ready')return{left:c,right:'NEXT: DEPTH'};if(s.phase==='z')return{left:c,right:c==='ALL DEPTH'?'USE ALL DEPTH':'DRAW DEPTH'};if(s.phase==='z-ready')return{left:c,right:'SAVE VOLUME'};if(s.phase==='saved')return{left:c,right:c==='NAME'?'SET NAME':'SAVE REGION'};return{left:'REGION',right:'SELECT'}}
function state(){const l=labels();return{phase:s.phase,selectedCount:s.cells.length,gridShape:'FLOW',tierIndex:s.minTier,pending:s.pending,exitRequested:false,regionId:s.regionId,regionName:s.name,caseIndex:s.caseIndex,caseCount:activeCases().length,caseLabel:activeCase(),leftLabel:l.left,rightLabel:l.right}}
function publish(){post({type:'controller-state',state:state()})}
function render(){stage.dataset.regionVolumePhase=s.phase;stage.dataset.regionFlowCase=activeCase();stage.classList.remove('region-tier-previewing','region-selection-only');stage.dataset.regionEntry='marker';world.style.display='block';world.style.visibility='visible';world.style.opacity='1';let m='';if(s.xy.length)m+=poly(s.xy);for(const n of s.cells){const c=n%s.cols,r=Math.floor(n/s.cols);m+=`<rect class="fillcell" x="${c*1000/s.cols}" y="${r*1000/s.rows}" width="${1000/s.cols}" height="${1000/s.rows}"/>`}if((s.phase==='z'||s.phase==='z-ready')&&s.z.length){m+=poly(s.z);const b=bnds(s.z);m+=`<rect class="zband" x="0" y="${b.minY*1000}" width="1000" height="${(b.maxY-b.minY)*1000}"/>`}svg.innerHTML=m;publish()}
function enterRegionView(){s.zoom=world.style.transform||s.zoom||original.transform;try{base.showAllParallax?.()}catch{}world.style.transformOrigin='50% 50%';world.style.transform=`${s.zoom} rotateX(15deg) scale(.96)`;world.style.maskImage='none';world.style.webkitMaskImage='none'}function restoreZoom(){world.style.transformOrigin=original.origin;world.style.transform=s.zoom||original.transform;world.style.maskImage=original.mask;world.style.webkitMaskImage=original.webkitMask;world.style.clipPath=original.clip}
function reduce(){const b=bnds(s.xy);if(!b)return;const sc=Math.min(1/Math.max(.02,b.maxX-b.minX),1/Math.max(.02,b.maxY-b.minY))*.78,cx=(b.minX+b.maxX)/2,cy=(b.minY+b.maxY)/2;world.style.transformOrigin=`${cx*100}% ${cy*100}%`;world.style.transform=`${s.zoom} rotateX(15deg) scale(${sc.toFixed(4)})`;world.style.clipPath=`polygon(${s.xy.map(q=>`${q.x*100}% ${q.y*100}%`).join(',')})`}
function finish(){s.drawing=false;if(s.phase==='xy'){s.cells=cells();s.boundary=boundary();if(s.cells.length){allZ();s.phase='xy-ready'}}else if(s.phase==='z'){deriveZ();s.phase='z-ready'}render()}
svg.addEventListener('pointerdown',e=>{if(!['xy','z'].includes(s.phase))return;e.preventDefault();s.drawing=true;s.pid=e.pointerId;svg.setPointerCapture?.(e.pointerId);const q=pnt(e);if(s.phase==='xy')s.xy=[q];else s.z=[q];render()});svg.addEventListener('pointermove',e=>{if(!s.drawing||e.pointerId!==s.pid)return;e.preventDefault();const a=s.phase==='xy'?s.xy:s.z,q=pnt(e);if(!a.length||dist(a[a.length-1],q)>.006)a.push(q);if(a.length>5&&dist(a[0],q)<.035){a.push({...a[0]});finish()}else render()});svg.addEventListener('pointerup',e=>{if(!s.drawing||e.pointerId!==s.pid)return;e.preventDefault();const a=s.phase==='xy'?s.xy:s.z;if(a.length>=3){a.push({...a[0]});finish()}else{s.drawing=false;render()}});svg.addEventListener('pointercancel',()=>{s.drawing=false;render()});
function claim(name=''){if(!s.cells.length||s.pending)return false;s.pending=true;s.name=String(name||s.name||'').trim()||'New Region';const b=bnds(s.xy);post({type:'create-region',version:2,name:s.name,cells:s.cells,boundaryCells:s.boundary,boundaryGridColumns:64,boundaryGridRows:64,canonicalMinX:b.minX,canonicalMinY:b.minY,canonicalMaxX:b.maxX,canonicalMaxY:b.maxY,viewMinX:b.minX,viewMinY:b.minY,viewMaxX:b.maxX,viewMaxY:b.maxY,viewZoomRatio:1,minTierIndex:s.minTier,maxTierIndex:s.maxTier,tierIndex:s.minTier,sourceLayerOffsets:Array.from({length:LPT},(_,i)=>i)});render();return true}
function step(axis,direction){const d=Math.sign(Number(direction)||0);if(!d)return false;const list=activeCases();if(String(axis||'').toLowerCase()==='x'||String(axis||'').toLowerCase()==='y'){s.caseIndex=(s.caseIndex+d+list.length)%list.length;render();return true}return false}
function select(){publish();return true}
function primary(name=''){const c=activeCase();if(s.phase==='xy-ready'){allZ();s.caseIndex=0;enterRegionView();s.phase='z';s.z=[];render();return true}if(s.phase==='z'&&c==='ALL DEPTH'){allZ();s.phase='z-ready';render();return true}if(s.phase==='z-ready'){reduce();s.caseIndex=0;s.phase='saved';render();return true}if(s.phase==='saved'&&c==='NAME'){if(String(name||'').trim())s.name=String(name).trim();s.caseIndex=1;render();return true}if(s.phase==='saved'&&c==='SAVE REGION')return claim(name);return false}
function secondary(){const c=activeCase();if(s.phase.startsWith('xy')){if(c==='CROP VIEW'){const b=bnds(s.xy);if(b)world.style.clipPath=`polygon(${s.xy.map(q=>`${q.x*100}% ${q.y*100}%`).join(',')})`;render();return true}s.xy=[];s.cells=[];s.boundary=[];s.phase='xy';render();return true}if(s.phase.startsWith('z')){if(c==='ALL DEPTH'){allZ();s.phase='z-ready'}else{s.z=[];s.phase='z'}render();return true}return false}
function back(){if(s.phase==='z'||s.phase==='z-ready'){restoreZoom();s.caseIndex=0;s.phase='xy-ready';render();return true}if(s.phase==='saved'){world.style.clipPath='';enterRegionView();s.caseIndex=0;s.phase='z-ready';render();return true}post({type:'home'});return true}
function resume(){if(document.visibilityState==='hidden')return;requestAnimationFrame(()=>{try{base.showAllParallax?.()}catch{}stage.classList.remove('region-tier-previewing','region-selection-only');stage.dataset.regionEntry='marker';world.style.display='block';world.style.visibility='visible';world.style.opacity='1';if(loading)loading.hidden=true;render();post({type:'ready',resume:true})})}
document.addEventListener('visibilitychange',resume);window.addEventListener('pageshow',resume);window.addEventListener('focus',resume);
window.addEventListener('message',e=>{if(e.origin!==location.origin)return;const d=e.data;if(!d||d.source!=='shaelvien-regiondefiner-host')return;if(d.type==='world-source'){const w=d.worldSource||{};s.cols=Math.max(1,Number(w.gridColumns)||30);s.rows=Math.max(1,Number(w.gridRows)||30);resume()}if(d.type==='region-created'){s.pending=false;s.regionId=String(d.region?.id||'');s.phase='claimed';render()}if(d.type==='error'){s.pending=false;render()}});
Object.assign(base,{enterRegionController(){stage.classList.remove('region-tier-previewing','region-selection-only');stage.dataset.regionEntry='marker';if(NEW_FLOW){s.phase='xy';s.caseIndex=0}resume();return true},getRegionControllerState:state,publishRegionControllerState(){publish();return true},regionControllerStep:step,regionControllerSelect:select,regionControllerPrimary:primary,regionControllerSecondary:secondary,regionControllerBack:back});render();post({type:'ready'});
}boot();})();
